#!/usr/bin/env bash
# Description: Add the complete Company Memberships and Roles backend module.

set -Eeuo pipefail

PROJECT_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
PATCH_FILE="$(mktemp)"
cleanup() { rm -f "${PATCH_FILE}"; }
trap cleanup EXIT

base64 -d <<'COMPANY_MEMBERSHIPS_PATCH' | gzip -d > "${PATCH_FILE}"

COMPANY_MEMBERSHIPS_PATCH

if git -C "${PROJECT_ROOT}" apply --reverse --check "${PATCH_FILE}" >/dev/null 2>&1; then
    printf '%s\n' "Company Memberships implementation is already present."
elif git -C "${PROJECT_ROOT}" apply --check "${PATCH_FILE}"; then
    git -C "${PROJECT_ROOT}" apply "${PATCH_FILE}"
    printf '%s\n' "Company Memberships implementation generated."
else
    printf '%s\n' "ERROR: Company Memberships patch conflicts with the current source tree." "No implementation files were changed." >&2
    exit 1
fi

if [[ -x "${PROJECT_ROOT}/scripts/maintenance/update-project-status.sh" ]]; then
    "${PROJECT_ROOT}/scripts/maintenance/update-project-status.sh"
fi

printf '%s\n' "Migration 0006 is generated without being applied by this script."
